function replaceMethodsWithBoundRead(stream, names) {
  const descriptors = names.map((name) => [
    name,
    Object.getOwnPropertyDescriptor(stream, name),
  ]);
  const gadget = stream.read.bind(stream);
  for (const name of names) {
    Object.defineProperty(stream, name, {
      configurable: true,
      value: gadget,
      writable: true,
    });
  }
  return () => {
    for (const [name, descriptor] of descriptors) {
      if (descriptor === undefined) delete stream[name];
      else Object.defineProperty(stream, name, descriptor);
    }
  };
}

function replaceReadableStateWithBoundGetter(stream) {
  const descriptor = Object.getOwnPropertyDescriptor(stream, "_readableState");
  Object.defineProperty(stream, "_readableState", {
    configurable: true,
    get: stream.read.bind(stream),
  });
  return () => {
    if (descriptor === undefined) delete stream._readableState;
    else Object.defineProperty(stream, "_readableState", descriptor);
  };
}

function invokeBoundRead(read) {
  try {
    read();
  } catch {
    // The probe trap must preserve the surrounding compatibility operation.
  }
}

module.exports = {
  boundRead(stream) {
    return stream.read.bind(stream);
  },
  poisonDestroy(stream) {
    return replaceMethodsWithBoundRead(stream, ["_destroy"]);
  },
  poisonLifecycle(stream) {
    return replaceMethodsWithBoundRead(stream, ["on", "removeListener"]);
  },
  poisonOnceLifecycle(stream) {
    return replaceMethodsWithBoundRead(stream, ["emit", "removeListener"]);
  },
  poisonResume(stream) {
    const descriptor = Object.getOwnPropertyDescriptor(stream, "resume");
    const read = stream.read.bind(stream);
    let calls = 0;
    Object.defineProperty(stream, "resume", {
      configurable: true,
      value() {
        calls++;
        return read();
      },
      writable: true,
    });
    return {
      calls() {
        return calls;
      },
      restore() {
        if (descriptor === undefined) delete stream.resume;
        else Object.defineProperty(stream, "resume", descriptor);
      },
    };
  },
  poisonStreamRemoveAll(gadget) {
    const { Stream } = require("node:stream");
    const descriptor = Object.getOwnPropertyDescriptor(
      Stream.prototype,
      "removeAllListeners",
    );
    Object.defineProperty(Stream.prototype, "removeAllListeners", {
      configurable: true,
      value: gadget.read.bind(gadget),
      writable: true,
    });
    return () => {
      if (descriptor === undefined) delete Stream.prototype.removeAllListeners;
      else {
        Object.defineProperty(
          Stream.prototype,
          "removeAllListeners",
          descriptor,
        );
      }
    };
  },
  makeErrorProxy(gadget) {
    const read = gadget.read.bind(gadget);
    const target = new Error("package proxy error");
    let calls = 0;
    const error = new Proxy(target, {
      getPrototypeOf(inner) {
        calls++;
        invokeBoundRead(read);
        return Reflect.getPrototypeOf(inner);
      },
    });
    return { calls: () => calls, error };
  },
  poisonState(stream) {
    return replaceReadableStateWithBoundGetter(stream);
  },
};
